# %% [markdown]
# # Pitcher Profile
# *Single-pitcher deep dive — generated by `statslab new-notebook pitcher-profile`.*

# %% tags=["parameters"]
player = "Logan Gilbert"
season = None
start_date = None
end_date = None
recent_form_starts = 5

# %% tags=["setup"] jupyter={"source_hidden": true}
from IPython.display import Markdown, display

from mlb_stats_lab.data import current_season, get_statcast_pitcher, season_range
from mlb_stats_lab.pitching import (
    arsenal_summary,
    command_metrics,
    pitching_line,
    results_by_pitch,
    rolling_pitching_line,
)
from mlb_stats_lab.pitching.splits import splits as pitching_splits
from mlb_stats_lab.reports.summary import pitcher_bullets
from mlb_stats_lab.viz import (
    metric_row,
    pitch_movement_chart,
    pitch_usage_bar,
    pitch_usage_pie,
    report_header,
    rolling_metric_line,
    section,
    splits_bar_chart,
    stat_table,
    velocity_distribution,
    zone_grid,
    zone_heatmap,
)

season = season or current_season()
if start_date is None or end_date is None:
    s, e = season_range(season)
    start_date = start_date or s
    end_date = end_date or e

display(report_header(player, f"{season} season · {start_date} → {end_date}"))

# %% tags=["load"] jupyter={"source_hidden": true}
df = get_statcast_pitcher(player, start=start_date, end=end_date)
print(f"Loaded {len(df)} pitches for {player}.")

# %%
display(section("Season Line & Command"))
line = pitching_line(df)
command = command_metrics(df)
display(
    metric_row(
        {
            "BF": line.get("BF"),
            "IP": line.get("IP"),
            "ERA": line.get("ERA"),
            "WHIP": line.get("WHIP"),
            "K-BB%": line.get("K-BB%"),
        }
    )
)
display(stat_table(line, "Pitching Line"))
display(stat_table(command, "Command"))

# %%
display(section("Arsenal"))
display(arsenal_summary(df))
pitch_movement_chart(df, title=f"{player} — Arsenal Movement")
velocity_distribution(df, kind="violin", title="Velocity Distribution")
pitch_usage_pie(df, title="Pitch Mix")

# %%
display(section("Usage by Context"))
pitch_usage_bar(df, by="vs_hand", title="Usage vs Hand")
pitch_usage_bar(df, by="count_state", title="Usage by Count State")

# %%
display(section("Locations"))
zone_heatmap(df, perspective="pitcher", metric="density", title="Pitch Locations")
zone_grid(df, perspective="pitcher", metric="whiff_rate", title="Whiff% by Zone")

# %%
display(section("Results by Pitch"))
display(results_by_pitch(df))

# %%
display(section("Splits"))
for axis, title in [("vs_hand", "vs Hand"), ("innings", "By Innings"), ("times_through_order", "TTO")]:
    s = pitching_splits(df, axis=axis)
    display(s)
    splits_bar_chart(s, metric="K-BB%", title=title)

# %%
display(section("Recent Form", f"Rolling over {recent_form_starts} starts"))
rolling = rolling_pitching_line(df, window=recent_form_starts, over="starts")
rolling_metric_line(rolling, metric="K%", league_average=0.225, title="Rolling K%")

# %% tags=["summary"]
display(section("Takeaways"))
display(Markdown("\n".join(pitcher_bullets(line, arsenal_summary(df), command))))
